INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0042e21-b17e-4a37-b4ff-6d9490039d07', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "603f8aca-1426-489b-affb-01ebfd7c0a00", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "dbf803be-3d36-4db8-b6a1-1b24dd185360", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "629a2d6b-af5a-4144-96b6-d2f123c44042", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b817dab7-6304-4c45-9dfe-c8f45c13dd75", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "86d1f9d6-8721-40ce-82d8-2b03730db1ad", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "49475664-508b-4377-a547-c28b31259f4a", "text": "Igaz", "isCorrect": true}, {"id": "c9643b94-f496-442c-8e9b-6a61371aefcb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b5e43674-fe0c-4f3f-8728-3257fce1521d", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "a0197025-1b8e-4e55-a1a8-09590e94a12b", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "38770f02-17db-4708-bd6f-f4db5178a570", "text": "Igaz", "isCorrect": true}, {"id": "45332765-364c-44c0-88de-f624d83599e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b09ae6aa-b45f-4489-ac23-0925241c632c', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "381e8a83-f50b-4f07-8834-e68b801eb075", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "dbfdc01a-dcd8-4d8f-8d92-d4696f419a8b", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "57f0c1c4-cd86-41b0-a032-a999e8e28e89", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "bb5c4fcc-b8f8-413e-ae75-996aca455cc5", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "ee56b05d-6fac-4f28-8fcb-bcfece3d77d2", "text": "Igaz", "isCorrect": true}, {"id": "1fb9aba2-7837-4ba5-b855-8dbd6def7b62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9158a5d-536d-46f8-a341-1c64c9a11cc2", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "cd02e60c-03c2-4060-9217-4f3c458e335a", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "978028bb-3e38-44d1-8683-b94cc61304e4", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "ca3c2338-0cb7-4e44-9d3b-b554a6d3073e", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "dde4ef6d-178a-40a9-8c2d-13983ba78520", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "8574501d-70f0-4342-8ca5-24aac486927a", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "af0a51f7-d357-4ac8-b75e-74f010a61ee7", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "6cf7f3cc-a9f1-48b4-8d55-9c97d89b9148", "text": "Igaz", "isCorrect": true}, {"id": "0a7423e7-e43f-406e-98c4-323248ba186b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ab2f434a-c1e4-4f58-8c80-0bc44d93c140', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a5c2c7d3-278d-4652-906e-f3417ae10429", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "04af1909-2463-4a7b-94a3-6c2aa7927ccc", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "ef5252a8-0843-4163-9f4d-d1fbfde36c9a", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "ef596cde-a0e5-4cf9-8a55-8b1620d5e163", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "13d306e9-59b9-4f76-a7ea-c790b114667c", "text": "Pontosan 5", "isCorrect": false}, {"id": "da65aefd-6854-482a-be06-7103bc89cdb7", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "4f09db06-44bb-4083-888e-a7d0cddf2527", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "a030cb92-a605-4854-9b01-2fbc2508c458", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "b2c08182-7d28-4712-a7f8-178d6255713c", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "664bbb9d-6075-490b-9cd9-95a639241a09", "text": "Pontosan 5", "isCorrect": false}, {"id": "46a00190-f3a2-4824-be07-fa68278a1994", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "3c5e5f98-af09-485c-ba47-bc5d500813a4", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "3c0ae3b3-e64a-4c1d-a211-8bc2f3ddf17b", "text": "Igaz", "isCorrect": true}, {"id": "5466fe0d-b8a9-492b-a194-0f99d2ce6d0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0c784982-9726-43d1-ad87-6ae4d3abf20b", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "ccc60c3d-f001-4f65-91e4-97c8f500e635", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "5430da5d-2e03-43e6-8b1c-7c96c9a43366", "text": "Igaz", "isCorrect": true}, {"id": "3dfc1288-6437-4029-912d-d538de390b93", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4d50d3af-d4f9-4d70-9e10-5a63b620fb7b", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('edd1a33f-2d69-4245-863b-a8700515fd1a', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a0ec66de-a54b-4fcd-8d57-13533bf8d17d", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "4634ade7-1f19-4d6a-932e-677cb8f44a21", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "be030d01-c651-4c17-ac60-90c68c7723e0", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "84170a2e-03d2-47b1-8f51-3938d4c4f18e", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b289be98-b339-4b9a-b25c-0a3060748c55", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "c306873d-7662-4510-8359-9d7d85b1a812", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "12de0b76-b90b-4a36-9e48-f80193bc9984", "text": "Igaz", "isCorrect": true}, {"id": "3f7ce12a-8610-4308-8815-6fd09676af4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d88e2728-05e8-4c09-a1af-09ab0713decd", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7cccdd65-c993-4b15-87a1-609e8c8ec7dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cdf5d82b-ffdf-42fe-b678-9b2b61043773", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "e43e65ac-6a01-42cc-9db9-289a201ba543", "text": "1 : 3", "isCorrect": true}, {"id": "2d00c948-6c34-4416-8a46-e0f541dcfca2", "text": "1 : 4", "isCorrect": false}, {"id": "4248398c-0146-4943-911a-c3173276b8c0", "text": "2 : 3", "isCorrect": false}, {"id": "d1ccc797-b6f3-4087-a008-3572846d0dcc", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "c66ce2bf-43ec-4f9a-b197-fa8bf0906891", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "d8bb0f83-a027-465f-be7a-64ae60f7e096", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6bc15673-9430-432a-b4f2-a6a32b1d9025", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "8171e1c0-e2ff-4862-9fbe-218f327413f4", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e899de89-4a38-4dc5-a84f-c685cf3daff7", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "01c2ca71-e1f6-4af6-80a5-e8c0ad6a4dd0", "text": "Igaz", "isCorrect": true}, {"id": "99ed6ccf-d756-4fa6-b544-f801ec4aa389", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f58a39f2-daa1-427e-83fa-7a1339fa4d93", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c9538f50-8dc6-4c74-a607-8b41386729c2', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "143a2de4-40b3-45e0-ba01-ab6eb5057d35", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "5e9f93aa-0a8b-4a8d-bb4e-35b74e5e26f3", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "e9c41ca2-1749-4ffe-8bd1-1b1799effc26", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "60a018f4-56a9-436c-bcf2-b7d0fdadc0f0", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "8ab44eeb-b3de-4b40-9640-8d9a2f5d7a1b", "text": "Igaz", "isCorrect": true}, {"id": "423bb632-e7fb-46ef-ae4c-71a10f6d766e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4fa723e-aa70-4164-b2a4-a52bfb7cf8f7", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "528490de-8c2b-43d6-aba4-0defabb1fc81", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "790c063e-b890-4ea4-a305-297dfa2ba826", "text": "Igaz", "isCorrect": true}, {"id": "f3059f86-afd2-4c9b-b555-2509370f799d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f4e6439b-ef73-4685-be68-39307a22440a", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4b45182b-34d9-437b-b98f-483ee3b8c1a4', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0d82da41-57d6-4d57-985d-3ce0487577a3", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "f9755400-72a4-4366-9b51-461ec43d9e10", "text": "2 : 7", "isCorrect": true}, {"id": "16d9ad9f-b040-4a46-aca0-39d420457608", "text": "1 : 35", "isCorrect": false}, {"id": "0e72a578-d100-4383-8a48-6de38160bb5d", "text": "2 : 5", "isCorrect": false}, {"id": "949ff0b0-3276-4164-8a25-26f703c91d27", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "82416f0e-5f84-42e7-acd6-cc434aae15be", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "b2706f82-8a22-4c73-8781-697238879165", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "ffe9cfcb-0c04-4062-a003-9f66c5f74742", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "c30ba9d0-96be-4d1e-85e4-cb46a0f76310", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "6c5eb887-3a2d-40af-9087-383f69f03d86", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "5df7029f-363f-418c-a6e4-1ecf71ebcd15", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "25edaadb-a7da-4d45-bf6f-f9996c036c09", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "9c2b6a34-24e2-4e2b-9a44-fe55b50d7934", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "d400d5bb-6071-4948-a4be-04ef7a49511b", "text": "Igaz", "isCorrect": true}, {"id": "082478a9-f911-42aa-bb33-3d9b46784963", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bde37dfd-d059-421b-ba80-d746c62b0437", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('00e26a85-bcb8-4ecc-af50-a996a9f5224c', '21feff02-016d-46e2-bb9d-c27495133b1b', '97. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b69016f6-6771-414f-a397-dc42af80892a", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "3b0480b5-4ccc-47fc-8087-16897ce22cae", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "13122cac-3436-4e6f-9e04-708722ec33a0", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "ef75bb33-4ee8-431c-b4db-4abb5cd4ca21", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "e46ded72-6aa4-4638-afc6-d1ea38757977", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "214043e3-8876-4893-acd0-22d408b21a80", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "7443f34d-519f-43b1-8c6f-156724bf45c9", "text": "Igaz", "isCorrect": true}, {"id": "d9ff35a6-b958-4999-9f05-e4cf70a47808", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec449125-f779-4b55-b45a-2b70902c41f3", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "caa80d73-3004-4e1a-8c9b-613da3df5bab", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "6c8de001-4316-4e5d-b0ca-376fb7fe0d2a", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "9080f584-33fc-4555-b447-3ffdf7f95f3a", "text": "Igaz", "isCorrect": true}, {"id": "0509584a-6e15-48e8-bcd7-9783def3b56f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e0a1e28a-72c9-475f-8cc6-be7393bf174b", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b46e8a06-7f37-4b92-b106-199c6d02ba0a", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('676c8b7b-2fb4-4089-a437-9143b0c9d6f8', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3e78e061-2135-480b-a3e6-c25f0c76fcd5", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "3babbecb-b03f-4ebc-9eea-64ba2182cbfd", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "b6046103-287b-421e-822c-637b9d113b08", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "b42e24d4-1842-4a5c-ac8b-db3e24ed9f95", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "1427d7cc-bde6-472a-abbe-832ac499f2a0", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "05550d81-66b1-4d82-b0db-3864e4cb9f1f", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "838872e8-53f3-4978-9263-072093fa6353", "text": "Igaz", "isCorrect": true}, {"id": "201fa361-38be-4ee8-a5e5-2023c9f807cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "44eab280-383e-4925-a85c-f13a83c4abf6", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dcf3ee04-7c50-4c86-8b8e-5a640075ba78', '21feff02-016d-46e2-bb9d-c27495133b1b', '99. óra: Hosszúság, tömeg, idő II.', 'Összetett mértékegység-átváltási feladatok és gyakorlás.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "39b9f073-b66f-4cd2-9ba6-801cd199ed32", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "a23bc2cb-b456-44d6-8017-dc632dc9fde3", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "9ec43164-922b-4d7e-85cb-ba0d1b5b97a5", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "2c67ed73-0ae1-4d75-a374-9d9a69669474", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "4db8a8f1-8ac0-4370-898b-914c125fa4e2", "text": "Igaz", "isCorrect": true}, {"id": "84fc1be2-22e2-4d33-9310-659533efe259", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7afa1c53-f39b-4217-88f0-676f2a6a342b", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "121431bb-f1a8-4b43-a0f7-3f53a467ccef", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "a3425d23-a6ed-4740-aad6-f5ce3ca9e5d3", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "85d44f4d-6a0d-4a7e-8b2f-8f9d467f8dbb", "text": "Igaz", "isCorrect": true}, {"id": "690f9911-8f1c-4167-b0c3-51485050051b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());